        "0a093c2f646963743e0a3c2f646963743e0a3c2f706c6973743e0a" +
        "").chunked(2).map { it.toInt(16).toByte() }.toByteArray()

    @Test
    fun binaryAndXmlPropertyListsGiveTheSameTree() {
        assertTrue(Plist.isBinary(binary))
        assertEquals(Plist.parse(xml), Plist.parse(binary))
    }

    @Test
    fun anAppleShortcutIsImported() {
        val imported = ShortcutFile.import(binary, "Morning.shortcut")
        assertEquals("Morning", imported.name)
        assertEquals("rose", imported.colorKey) // Apple red
        val ids = imported.actions.map { it.identifier.substringAfterLast('.') }
        assertEquals(listOf("gettext", "conditional", "showresult", "conditional", "conditional", "unknown", "math", "dictionary", "delay"), ids)

        // text, its name and its id are kept
        assertEquals("AAAA-1", imported.actions[0].uuid)
        assertEquals("Greeting", imported.actions[0].outputName)

        // the If group: start, otherwise, end
        assertEquals(listOf(0, 1, 2), imported.actions.filter { it.identifier.endsWith("conditional") }.map { it.flow!!.role })
        val start = imported.actions[1]
        assertEquals(ParamValue.Choice("4"), start.params["WFCondition"]) // "Equals"
        assertEquals(ParamValue.Variable(VariableRef(VariableSource.ActionOutput("AAAA-1"))), start.params["WFInput"])

        // a text with a variable inside
        val show = imported.actions[2].params["Text"] as ParamValue.Text
        assertEquals(
            TokenString(listOf(TokenString.Part.Literal("Say "), TokenString.Part.Variable(VariableRef(VariableSource.ActionOutput("AAAA-1"))), TokenString.Part.Literal("!"))),
            show.value,
        )

        // Apple's Count became "Calculate > number of words"; the dictionary became a key / value block
        assertEquals(ParamValue.Choice("words"), imported.actions[6].params["WFMathOperation"])
        val dictionary = imported.actions[7]
        assertEquals(ParamValue.Text(TokenString.of("S")), dictionary.params["Key"])
        assertEquals(1, (dictionary.params["Items"] as ParamValue.Array).items.size)

        // an unknown block is kept, and reported
        assertEquals("com.example.unknown", imported.actions[5].identifier)
        assertTrue(imported.actions[5].params.values.all { it is ParamValue.Raw })
        assertTrue(imported.warnings.any { it.resolve("en").contains("unknown") })
        assertNotNull(imported.actions.last().params["WFDelayTime"])
    }

    @Test
    fun theXmlFormIsImportedToo() {
        assertEquals(ShortcutFile.import(binary, "a").actions.map { it.identifier }, ShortcutFile.import(xml, "a").actions.map { it.identifier })
    }

    @Test
    fun exportingThenImportingKeepsTheShortcut() {
        val first = ShortcutFile.import(binary, "Morning.shortcut")
        val exported = ShortcutFile.export("rose", first.actions)
        val again = ShortcutFile.import(exported.bytes, "Morning.shortcut")
        assertEquals(first.actions.map { it.identifier }, again.actions.map { it.identifier })
        assertEquals(first.actions.map { it.uuid }, again.actions.map { it.uuid })
        assertEquals(first.actions.map { it.flow }, again.actions.map { it.flow })
        assertEquals(first.actions[2].params["Text"], again.actions[2].params["Text"])
        assertEquals(first.actions[1].params["WFInput"], again.actions[1].params["WFInput"])
        assertEquals(first.actions[7].params["Key"], again.actions[7].params["Key"])
        assertEquals(first.actions[5].params, again.actions[5].params) // the unknown block survives untouched
        // the written file uses Apple's own keys
        val root = Plist.parse(exported.bytes) as Map<*, *>
        val written = root["WFWorkflowActions"] as List<*>
        val end = (written[4] as Map<*, *>)["WFWorkflowActionParameters"] as Map<*, *>
        assertEquals(2L, end["WFControlFlowMode"])
        assertEquals("G1", end["GroupingIdentifier"])
    }

    @Test
    fun filesThatAreNotShortcutsAreRefused() {
        try {
            ShortcutFile.import("AEA1".toByteArray() + ByteArray(40), "x.shortcut")
            fail("expected an error")
        } catch (e: ImportError) {
            assertEquals(ImportError.Reason.Signed, e.reason)
        }
        try {
            ShortcutFile.import("just some text".toByteArray(), "x.shortcut")
            fail("expected an error")
        } catch (e: ImportError) {
            assertEquals(ImportError.Reason.NotAShortcut, e.reason)
        }
    }
